import os, re, json
ROOT = "/Users/sebastianrogg/PycharmProjects/Hackathons & Projekte/WireClaim"
CASE_DIRS = [os.path.join(ROOT, "[PUBLIC] EHL Cases/cases"), os.path.join(ROOT, "var/cases")]
pats = set()

def safe(s):
    s = s.strip()
    if len(s) < 40 or '"' in s or '\\' in s: return None
    if not re.search(r'[a-z]{4}', s): return None
    if re.fullmatch(r'[-=_\s.*#]+', s): return None
    return s

for base in CASE_DIRS:
    if not os.path.isdir(base): continue
    for name in sorted(os.listdir(base)):
        d = os.path.join(base, name)
        if not name.startswith("case_") or not os.path.isdir(d): continue
        for fn in ("policy.txt", "description.txt"):
            p = os.path.join(d, fn)
            if not os.path.exists(p): continue
            for line in open(p, encoding="utf-8", errors="replace"):
                line = line.rstrip("\n")
                s = safe(line)
                if s: pats.add(s[:78])
                # also slice long paragraph lines into overlapping chunks
                t = line.strip()
                if len(t) > 90:
                    for i in range(0, len(t) - 70, 55):
                        c = safe(t[i:i+70])
                        if c: pats.add(c)

# invoice Line Item names from derived logs
names = set()
for sub in ("var/decisions", "var/reviews", "var/lessons"):
    d = os.path.join(ROOT, sub)
    if not os.path.isdir(d): continue
    for fn in os.listdir(d):
        if not fn.endswith(".json"): continue
        try: data = json.load(open(os.path.join(d, fn), encoding="utf-8"))
        except Exception: continue
        stack = [data]
        while stack:
            o = stack.pop()
            if isinstance(o, dict):
                for k, v in o.items():
                    if k == "name" and isinstance(v, str): names.add(v)
                    else: stack.append(v)
            elif isinstance(o, list): stack.extend(o)
for n in names:
    s = safe(n)
    if s: pats.add(s[:78])

pats = sorted(pats)
with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "patterns_full.txt"), "w") as f:
    for s in pats: f.write(s + "\n")
print("patterns:", len(pats), "| line-item names contributing:", sum(1 for n in names if safe(n)))
